# ==== OfficeQA MCP bundle install ====
apt-get update -qq
apt-get install -y -qq python3 zstd >/dev/null 2>&1

mkdir -p /opt/officeqa
cd /opt/officeqa

# Extract our zero-dependency MCP server code
base64 -d << 'OFFICEQA_BUNDLE_EOF' | tar xzf -

OFFICEQA_BUNDLE_EOF

# Download and stream-decompress the full corpus SQLite database (no temp file)
echo "Downloading + decompressing full corpus DB (streaming, ~931MB compressed → ~6.9GB)..."
mkdir -p /app/corpus
python3 -c "
import subprocess, urllib.request
resp = urllib.request.urlopen('http://209.38.74.239:9090/officeqa_lean_final.sqlite3.zst')
proc = subprocess.Popen(['zstd', '-d', '-o', '/app/corpus/officeqa_corpus.sqlite3', '-f'], stdin=subprocess.PIPE)
while True:
    chunk = resp.read(1048576)
    if not chunk:
        break
    proc.stdin.write(chunk)
proc.stdin.close()
proc.wait()
print('exit code:', proc.returncode)
"
echo "DB ready at /app/corpus/officeqa_corpus.sqlite3"

# Write the MCP launcher script
cat > /opt/officeqa/run_mcp.sh << 'OFFICEQA_WRAPPER_EOF'
#!/bin/bash
export OFFICEQA_SQLITE_DB="/app/corpus/officeqa_corpus.sqlite3"
cd /opt/officeqa
exec python3 -m server.mcp_stdio
OFFICEQA_WRAPPER_EOF
chmod +x /opt/officeqa/run_mcp.sh

# ==== End OfficeQA MCP bundle install ====
#!/bin/bash
set -euo pipefail

apt-get update
apt-get install -y curl

curl -o- https://raw.githubusercontent.com/nvm-sh/nvm/v0.40.2/install.sh | bash

export NVM_DIR="$HOME/.nvm"
# Source nvm with || true to handle nvm.sh's internal non-zero returns
\. "$NVM_DIR/nvm.sh" || true
# Verify NVM loaded successfully
command -v nvm &>/dev/null || { echo "Error: NVM failed to load" >&2; exit 1; }

nvm install 22
npm -v


npm i -g opencode-ai@latest


# Symlink node/npm/npx/opencode to /usr/local/bin so they're always on PATH
for bin in node npm npx opencode; do
    BIN_PATH="$(which "$bin")"
    if [ "$BIN_PATH" != "/usr/local/bin/$bin" ]; then
        ln -sf "$BIN_PATH" "/usr/local/bin/$bin"
    fi
done

# Install uv (needed for uvx-based stdio MCP servers)
if ! command -v uv &>/dev/null; then
    curl -LsSf https://astral.sh/uv/install.sh | sh
    export PATH="$HOME/.local/bin:$PATH"
fi

opencode --version